    long absVal = Math.abs((long) n);
    String s = Long.toString(absVal);
    int len = s.length();

    StringBuilder sb = new StringBuilder();

    // Determine the length of the first group (may be less than 3)
    int firstGroupLen = len % 3;
    if (firstGroupLen == 0) {
        firstGroupLen = 3;
    }

    // Append the first group
    sb.append(s.substring(0, firstGroupLen));

    // Append remaining groups, each preceded by a dot
    for (int i = firstGroupLen; i < len; i += 3) {
        sb.append('.');
        sb.append(s.substring(i, i + 3));
    }

    // Prepend negative sign if necessary
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

